tool_calls.arguments_json:
{"args":[],"function":"async () => {
  const asins = ['B01MY06P05', 'B01N1U9USQ', 'B01N6IT5IG', 'B07RN7WQ81', 'B07FKHHTYG'];
  const results = [];
  const input = document.querySelector('input[placeholder="按商品名称、ASIN、SKU 搜索"]');
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;

  for (const asin of asins) {
    input.focus();
    nativeSetter.call(input, asin);
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));
    input.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));

    await new Promise(r => setTimeout(r, 1500));

    const rows = Array.from(document.querySelectorAll('tr, [role="row"]')).filter(r => r.innerText.includes(asin));
    if (rows.length === 0) {
      results.push({ asin, status: 'not_found' });
      continue;
    }

    for (const row of rows) {
      const text = row.innerText;
      const ineligible = text.includes('不符合');
      const cb = row.querySelector('input[type="checkbox"], [role="checkbox"]');
      let checked = false;
      if (!ineligible && cb && !cb.checked) {
        cb.click();
        checked = cb.checked;
      }
      results.push({
        asin,
        ineligible,
        checked,
        skuSnippet: text.substring(0, 100).replace(/\n/g, ' ')
      });
    }
  }
  return results;
}","pageId":21,"toolSummary":"Process ASINs 1-5","waitForStableDom":false}

