args.value:
async () => {
  const dialog = document.querySelector('[role="dialog"]');
  if (!dialog) return 'No dialog found';
  const inputs = Array.from(dialog.querySelectorAll('input'));
  if (inputs.length < 2) return 'Not enough inputs';

  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;

  nativeSetter.call(inputs[0], '2026/10/31');
  inputs[0].dispatchEvent(new Event('input', { bubbles: true }));
  inputs[0].dispatchEvent(new Event('change', { bubbles: true }));

  nativeSetter.call(inputs[1], '2026/11/29');
  inputs[1].dispatchEvent(new Event('input', { bubbles: true }));
  inputs[1].dispatchEvent(new Event('change', { bubbles: true }));

  await new Promise(r => setTimeout(r, 300));

  const applyBtn = Array.from(dialog.querySelectorAll('button')).find(b => b.innerText && b.innerText.includes('应用'));
  if (applyBtn) {
    applyBtn.click();
    return { applied: true, input0: inputs[0].value, input1: inputs[1].value };
  }
  return { applied: false };
}

