{"function":"() => {
  let hc = window.Highcharts;
  if (!hc) {
    for (let i = 0; i < window.frames.length; i++) {
      try {
        if (window.frames[i].Highcharts) {
          hc = window.frames[i].Highcharts;
          break;
        }
      } catch (e) {}
    }
  }

  // Also check if any element has jQuery or Highcharts reference
  const containers = Array.from(document.querySelectorAll('.highcharts-container'));
  let chartInstances = [];

  containers.forEach(container => {
    // Check properties on container or container.parentElement
    const el = container.parentElement;
    for (let k in el) {
      if (el[k] && typeof el[k] === 'object' && el[k].series) {
        chartInstances.push(el[k]);
      }
    }
  });

  if (hc && hc.charts) {
    chartInstances = hc.charts.filter(Boolean);
  }

  // If not found directly, let's look for Highcharts in any global property
  if (chartInstances.length === 0) {
    for (let k of Object.getOwnPropertyNames(window)) {
      try {
        if (window[k] && window[k].charts && Array.isArray(window[k].charts)) {
          hc = window[k];
          chartInstances = hc.charts.filter(Boolean);
          break;
        }
      } catch (e) {}
    }
  }

  return {
    foundCharts: chartInstances.length,
    charts: chartInstances.map(c => ({
      title: c.title ? c.title.textStr : (c.options && c.options.title ? c.options.title.text : ''),
      series: c.series ? c.series.map(s => ({
        name: s.name,
        optionsName: s.options ? s.options.name : '',
        data: s.data ? s.data.map(d => ({ x: d.x, y: d.y, category: d.category, name: d.name })) : []
      })) : []
    }))
  };
