() => {
  const container = document.querySelector('.highcharts-container');
  if (!container) return 'no container';
  const parent = container.parentElement;

  // Let's inspect React Fiber or Angular or Vue
  const reactKey = Object.keys(parent).find(k => k.startsWith('__reactFiber') || k.startsWith('__reactInternalInstance'));
  let reactData = null;
  if (reactKey) {
    let fiber = parent[reactKey];
    // Traverse up to find props
    let curr = fiber;
    while (curr && !reactData) {
      if (curr.memoizedProps && (curr.memoizedProps.series || curr.memoizedProps.data || curr.memoizedProps.chartOptions)) {
        reactData = {
          hasSeries: !!curr.memoizedProps.series,
          keys: Object.keys(curr.memoizedProps)
        };
      }
      curr = curr.return;
    }
  }

  // Check SVG elements directly
  const salesSvg = document.querySelectorAll('svg')[3]; // 4th svg
  const paths = salesSvg ? Array.from(salesSvg.querySelectorAll('.highcharts-series path')).map(p => ({
    class: p.getAttribute('class'),
    d: p.getAttribute('d'),
    stroke: p.getAttribute('stroke')
  })) : [];

  return {
    reactKey: !!reactKey,
    reactData,
    paths
  };
}

